input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://example.org/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?sensor ?ts WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_top_ZN_2" .
  ?sensor a brick:ElectricPowerSensor ;
          brick:hasLocation ?zone ;
          brick:hasProperty brick:Lighting .
  ?zone ref:hasExternalReference ?sensor .
  ?sensor ref:hasTimeseriesId ?ts .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://example.org/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?label }
}
